        if i &gt; start &amp;&amp; (*choices)[i] == (*choices)[i-1] {
            continue
        }
        // 試行：選択を行い、target, start を更新する
        *state = append(*state, (*choices)[i])
        // 次の選択に進む
        backtrackSubsetSumII(i+1, target-(*choices)[i], state, choices, res)
        // 復元：選択を取り消し、以前の状態に戻す
